package com.cardcombat;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;public final class RitualCommand implements CommandExecutor{private final CardCombatPlugin p;public RitualCommand(CardCombatPlugin p){this.p=p;}public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!(s instanceof Player)||a.length<2)return true;Player x=(Player)s,y=Bukkit.getPlayerExact(a[0]);if(y==null){x.sendMessage(ChatColor.RED+"Player not found.");return true;}x.sendMessage(p.rituals().start(x,y,a[1])?ChatColor.GREEN+"Ritual started.":ChatColor.RED+"Ritual could not start.");return true;}}
